45	/**
46	 * GOAP (Goal-Oriented Action Planning) Planner
47	 * Uses A* algorithm to find optimal action sequence
48	 */
49	export class GOAPPlanner {
50	  private actions: Action[];
51	
52	  constructor(actions: Action[]) {
53	    this.actions = actions;
54	  }
55	
56	  /**
57	   * Calculate heuristic distance to goal (number of unmet conditions)
58	   */
59	  private heuristic(state: WorldState, goal: WorldState): number {
60	    let distance = 0;
61	    for (const key in goal) {
62	      if (goal[key as keyof WorldState] && !state[key as keyof WorldState]) {
63	        distance++;
64	      }
65	    }
66	    return distance;
67	  }
68	
69	  /**
70	   * Check if all preconditions are met
71	   */
72	  private preconditionsMet(state: WorldState, preconditions: Partial<WorldState>): boolean {
73	    for (const key in preconditions) {
74	      if (preconditions[key as keyof WorldState] && !state[key as keyof WorldState]) {
75	        return false;
76	      }
77	    }
78	    return true;
79	  }
80	
81	  /**
82	   * Apply action effects to state
83	   */
84	  private applyEffects(state: WorldState, effects: Partial<WorldState>): WorldState {
85	    return { ...state, ...effects };
86	  }
87	
88	  /**
89	   * Find optimal plan using A* search
90	   */
91	  public plan(currentState: WorldState, goalState: WorldState, userGoal: string): Step[] {
92	    interface Node {
93	      state: WorldState;
94	      actions: Action[];
95	      cost: number;
96	      heuristic: number;
97	    }
98	
99	    const openList: Node[] = [];
100	    const closedList: Set<string> = new Set();
101	
102	    // Start node
103	    openList.push({
104	      state: currentState,
105	      actions: [],
106	      cost: 0,
107	      heuristic: this.heuristic(currentState, goalState),
108	    });
109	
110	    while (openList.length > 0) {
111	      // Sort by total cost (cost + heuristic)
112	      openList.sort((a, b) => (a.cost + a.heuristic) - (b.cost + b.heuristic));
113	      
114	      const current = openList.shift()!;
115	      const stateKey = JSON.stringify(current.state);
116	
117	      // Check if goal reached
118	      if (this.heuristic(current.state, goalState) === 0) {
119	        // Convert actions to steps
120	        return current.actions.map(action => action.stepGenerator(userGoal));
121	      }
122	
123	      if (closedList.has(stateKey)) continue;
124	      closedList.add(stateKey);
125	
126	      // Try all applicable actions
127	      for (const action of this.actions) {
128	        if (this.preconditionsMet(current.state, action.preconditions)) {
129	          const newState = this.applyEffects(current.state, action.effects);
130	          const newStateKey = JSON.stringify(newState);
131	
132	          if (!closedList.has(newStateKey)) {
133	            openList.push({
134	              state: newState,
135	              actions: [...current.actions, action],
136	              cost: current.cost + action.cost,
137	              heuristic: this.heuristic(newState, goalState),
138	            });
139	          }
140	        }
141	      }
142	    }
143	
144	    // No plan found - return empty array
145	    return [];
146	  }
147	}
