168	  if (lowerGoal.includes("analyze")) action = "analyze";
169	  if (lowerGoal.includes("investigate")) action = "investigate";
170	  if (lowerGoal.includes("compare")) action = "compare";
171	  if (lowerGoal.includes("evaluate")) action = "evaluate";
172	
173	  // Extract keywords (simple approach - words > 4 chars)
174	  const keywords = goal
175	    .split(/\s+/)
176	    .filter(word => word.length > 4)
177	    .slice(0, 5);
178	
179	  return { domain, action, keywords };
180	}
