160	  /**
161	   * Load configuration from all sources
162	   */
163	  async load(): Promise<LoadedConfig> {
164	    const warnings: string[] = [];
165	
166	    // Start with defaults
167	    let config: SystemConfig = { ...defaultSystemConfig };
168	    let source: ConfigSource = 'default';
169	    let path: string | undefined;
170	
171	    // Try to load from file
172	    for (const searchPath of this.searchPaths) {
173	      const configPath = await findConfigFile(searchPath);
174	      if (configPath) {
175	        try {
176	          const fileConfig = await loadJsonConfig(configPath);
177	          const validation = validateSystemConfig(fileConfig);
178	
179	          if (validation.success) {
180	            config = mergeWithDefaults(validation.data!, defaultSystemConfig) as SystemConfig;
181	            source = 'file';
182	            path = configPath;
183	            break;
184	          } else {
185	            // Config file exists but doesn't match the strict schema.
186	            // Merge whatever valid object fields exist with defaults and continue.
187	            // This handles partial configs, legacy configs, and simple key-value files.
188	            if (fileConfig && typeof fileConfig === 'object' && !Array.isArray(fileConfig)) {
189	              const partial = fileConfig as Record<string, unknown>;
190	              const merged = { ...defaultSystemConfig } as Record<string, unknown>;
191	              for (const key of Object.keys(partial)) {
192	                if (partial[key] && typeof partial[key] === 'object' && !Array.isArray(partial[key])) {
193	                  merged[key] = { ...(merged[key] as Record<string, unknown> || {}), ...(partial[key] as Record<string, unknown>) };
194	                }
195	              }
196	              config = merged as SystemConfig;
197	              source = 'file';
198	              path = configPath;
199	            }
200	            // Always break on first found config file — don't search further
201	            break;
202	          }
203	        } catch (error) {
204	          warnings.push(`Failed to load config from ${configPath}: ${(error as Error).message}`);
205	        }
206	      }
207	    }
208	
209	    // Merge with environment variables
210	    const envConfig = loadEnvConfig();
211	    if (Object.keys(envConfig).length > 0) {
212	      config = this.deepMerge(config, envConfig) as SystemConfig;
213	      source = source === 'default' ? 'env' : 'merged';
214	    }
215	
216	    return {
217	      config,
218	      source,
219	      path,
220	      warnings: warnings.length > 0 ? warnings : undefined,
221	    };
222	  }
