224	  /**
225	   * Load configuration from specific file
226	   */
227	  async loadFromFile(filePath: string): Promise<LoadedConfig> {
228	    const absolutePath = resolve(filePath);
229	    const fileConfig = await loadJsonConfig(absolutePath);
230	    const validation = validateSystemConfig(fileConfig);
231	
232	    if (!validation.success) {
233	      throw new Error(`Invalid configuration: ${validation.errors?.map(e => e.message).join(', ')}`);
234	    }
235	
236	    const config = mergeWithDefaults(validation.data!, defaultSystemConfig) as SystemConfig;
237	
238	    return {
239	      config,
240	      source: 'file',
241	      path: absolutePath,
242	    };
243	  }
