245	  /**
246	   * Deep merge objects
247	   */
248	  private deepMerge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
249	    const result = { ...target };
250	
251	    for (const key of Object.keys(source)) {
252	      const sourceValue = source[key];
253	      const targetValue = target[key];
254	
255	      if (
256	        sourceValue &&
257	        typeof sourceValue === 'object' &&
258	        !Array.isArray(sourceValue) &&
259	        targetValue &&
260	        typeof targetValue === 'object' &&
261	        !Array.isArray(targetValue)
262	      ) {
263	        result[key] = this.deepMerge(
264	          targetValue as Record<string, unknown>,
265	          sourceValue as Record<string, unknown>,
266	        );
267	      } else if (sourceValue !== undefined) {
268	        result[key] = sourceValue;
269	      }
270	    }
271	
272	    return result;
273	  }
274	}
